CREATE TABLE IF NOT EXISTS "Branches" ("Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"Name" varchar(100) NOT NULL,"Active" boolean NOT NULL DEFAULT TRUE);
INSERT INTO "Branches" ("Name","Active") SELECT 'Sucursal Av. Sirai',TRUE WHERE NOT EXISTS(SELECT 1 FROM "Branches");
INSERT INTO "Branches" ("Name","Active") SELECT 'Sucursal Av. 6 de Agosto',TRUE WHERE (SELECT COUNT(*) FROM "Branches")=1;
CREATE TABLE IF NOT EXISTS "CashSessions" (
 "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"BranchId" integer NOT NULL REFERENCES "Branches"("Id") ON DELETE RESTRICT,
 "OpenedById" integer NOT NULL,"OpenedAt" timestamp without time zone NOT NULL,"ClosedAt" timestamp without time zone NULL,
 "OpenedBy" text NOT NULL,"ClosedBy" text NOT NULL DEFAULT '',"OpeningAmount" bigint NOT NULL,
 "CountedAmount" bigint NULL,"ExpectedAmount" bigint NULL,"Difference" bigint NULL,"QrTotal" bigint NULL,"CountedQr" bigint NULL,"QrDifference" bigint NULL,
 "OpeningDenominations" text NOT NULL DEFAULT '',"ClosingDenominations" text NOT NULL DEFAULT '',"Notes" text NOT NULL DEFAULT '',"Revision" text NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_CashSessions_OpenedById" ON "CashSessions"("OpenedById") WHERE "ClosedAt" IS NULL;
CREATE INDEX IF NOT EXISTS "IX_CashSessions_BranchId" ON "CashSessions"("BranchId");
CREATE TABLE IF NOT EXISTS "Coupons" (
 "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"Code" varchar(40) NOT NULL,"Description" text NOT NULL,"Type" text NOT NULL,"Value" numeric(18,2) NOT NULL,
 "Start" timestamp without time zone NOT NULL,"End" timestamp without time zone NOT NULL,"Active" boolean NOT NULL DEFAULT TRUE,
 "CustomerId" integer NULL REFERENCES "Customers"("Id") ON DELETE RESTRICT,"Revision" text NOT NULL,"GiftProductId" integer NULL,"GiftQuantity" integer NOT NULL DEFAULT 1
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Coupons_Code" ON "Coupons"("Code");
ALTER TABLE "Sales" ADD COLUMN IF NOT EXISTS "BranchId" integer NULL REFERENCES "Branches"("Id") ON DELETE RESTRICT;
ALTER TABLE "Sales" ADD COLUMN IF NOT EXISTS "CashSessionId" integer NULL REFERENCES "CashSessions"("Id") ON DELETE RESTRICT;
ALTER TABLE "Sales" ADD COLUMN IF NOT EXISTS "CreatedById" integer NULL;
ALTER TABLE "Sales" ADD COLUMN IF NOT EXISTS "CreatedBy" text NOT NULL DEFAULT '';
ALTER TABLE "Sales" ADD COLUMN IF NOT EXISTS "Revision" text NOT NULL DEFAULT md5(random()::text || clock_timestamp()::text);
ALTER TABLE "Sales" ADD COLUMN IF NOT EXISTS "CouponId" integer NULL REFERENCES "Coupons"("Id") ON DELETE RESTRICT;
ALTER TABLE "Sales" ADD COLUMN IF NOT EXISTS "CouponCode" text NOT NULL DEFAULT '';
ALTER TABLE "Sales" ADD COLUMN IF NOT EXISTS "CouponType" text NOT NULL DEFAULT '';
ALTER TABLE "Sales" ADD COLUMN IF NOT EXISTS "CouponValue" numeric(18,2) NOT NULL DEFAULT 0;
ALTER TABLE "Sales" ADD COLUMN IF NOT EXISTS "CouponProductId" integer NULL;
ALTER TABLE "Sales" ADD COLUMN IF NOT EXISTS "CouponQuantity" integer NOT NULL DEFAULT 0;
ALTER TABLE "Orders" ADD COLUMN IF NOT EXISTS "BranchId" integer NULL REFERENCES "Branches"("Id") ON DELETE RESTRICT;
ALTER TABLE "Orders" ADD COLUMN IF NOT EXISTS "CouponId" integer NULL REFERENCES "Coupons"("Id") ON DELETE RESTRICT;
ALTER TABLE "Orders" ADD COLUMN IF NOT EXISTS "CouponCode" text NOT NULL DEFAULT '';
ALTER TABLE "Orders" ADD COLUMN IF NOT EXISTS "CouponType" text NOT NULL DEFAULT '';
ALTER TABLE "Orders" ADD COLUMN IF NOT EXISTS "CouponValue" numeric(18,2) NOT NULL DEFAULT 0;
ALTER TABLE "Orders" ADD COLUMN IF NOT EXISTS "CouponProductId" integer NULL;
ALTER TABLE "Orders" ADD COLUMN IF NOT EXISTS "CouponQuantity" integer NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS "IX_Sales_BranchId" ON "Sales"("BranchId");
CREATE INDEX IF NOT EXISTS "IX_Sales_CreatedById" ON "Sales"("CreatedById");
CREATE TABLE IF NOT EXISTS "CouponRedemptions" (
 "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"CouponId" integer NOT NULL REFERENCES "Coupons"("Id") ON DELETE RESTRICT,
 "SaleId" integer NULL REFERENCES "Sales"("Id") ON DELETE RESTRICT,"OrderId" integer NULL REFERENCES "Orders"("Id") ON DELETE RESTRICT,
 "Released" boolean NOT NULL DEFAULT FALSE,"CreatedAt" timestamp without time zone NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_CouponRedemptions_CouponId" ON "CouponRedemptions"("CouponId") WHERE NOT "Released";
CREATE TABLE IF NOT EXISTS "SaleCorrections" (
 "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"SaleId" integer NOT NULL REFERENCES "Sales"("Id") ON DELETE RESTRICT,
 "CreatedUtc" timestamp without time zone NOT NULL,"Actor" text NOT NULL,"Reason" text NOT NULL,"BeforeJson" text NOT NULL,"AfterJson" text NOT NULL
);
